@api_view(["GET"])
@authentication_classes([])
@permission_classes([AllowAny])
def health_check(request):
	# Lightweight liveness probe: verifies Django is serving and SQLite is reachable.
	try:
		connection.ensure_connection()
	except Exception:  # noqa: BLE001 - any DB failure means unhealthy; never leak false ok
		return Response({"status": "error", "db": "unreachable"}, status=status.HTTP_503_SERVICE_UNAVAILABLE)
	return Response({"status": "ok", "db": "ok", "auth_required": getattr(settings, "REQUIRE_AUTH", False)})


@api_view(["POST"])
@authentication_classes([])
@permission_classes([AllowAny])
def login_view(request):
	# Public credential verification: stale/invalid Authorization headers must not block login.
	username = (request.data.get("username") or "").strip()
	password = request.data.get("password") or ""
	if not username or not password:
		return Response({"detail": "Username and password are required."}, status=status.HTTP_400_BAD_REQUEST)
	user = authenticate(request, username=username, password=password)
	if user is None:
		return Response({"detail": "Invalid username or password."}, status=status.HTTP_400_BAD_REQUEST)
	login(request, user)
	return Response({"id": user.id, "username": user.username})


@api_view(["POST"])
@authentication_classes([])
@permission_classes([AllowAny])
def logout_view(request):
	logout(request)
	return Response({"detail": "Logged out."})


@api_view(["GET"])
@permission_classes([AllowAny])
def auth_status(request):
	user = request.user
	is_authenticated = bool(user and user.is_authenticated)
	return Response(
		{
			"authenticated": is_authenticated,
			"user": {"id": user.id, "username": user.username} if is_authenticated else None,
			"auth_required": getattr(settings, "REQUIRE_AUTH", False),
		}
	)


